  222: { id: 222, name: "Cartel Pescadores", type: "misc", objType: 8, value: 0, graphic: 623, texto: "Gremio de Pescadores" },
  223: { id: 223, name: "Cartel", type: "misc", objType: 8, value: 0, graphic: 625, texto: "Hola aventurero, unos cuantos kilomentros al Norte se encuentra el pueblo de Ullathorpe y al Oeste encontraras la ciudad de Nix. Buena Suerte, viajero!" },
  224: { id: 224, name: "Cartel", type: "misc", objType: 8, value: 0, graphic: 624, texto: "Forasteros: Este Pueblo forma parte del Gran Imperio de Argentum, cualquier accion criminal sera reprimida por la Guardia Real. Todo criminal sera perseguido y ajusticiado.                                Ordenanza Real." },
  225: { id: 225, name: "Cartel Newbie Dungeon", type: "misc", objType: 8, value: 0, graphic: 626, texto: "Hola osados aventureros, sed bienvenidos en el Dungeon Newbie! Aqui podran entrenar sus habilidades sin correr ningun riesgo ya que el Dungeon esta fuertemente custodiado por la Guardia Imperial. Adentrandose encontraran criaturas perversas con las cuales podran luchar, tambien encontraran un Sacerdote para ser resucitados, provisiones, etc. Suerte y que lo disfruteis!" },
  226: { id: 226, name: "Cartel", type: "misc", objType: 8, value: 0, graphic: 628, texto: "Sigue el camino del Sur para ir a Nix, hacia al Oeste encontraras el peligroso bosque de Dorck." },
  227: { id: 227, name: "Cartel Bosque Dorck", type: "misc", objType: 8, value: 0, graphic: 627, texto: "Entrada al bosque de Dorck. Mantengase alejado, zona de peligro." },
