  700: { id: 700, name: "Anillo de los Dioses", type: "misc", objType: 18, value: 1500000, graphic: 4903, skHerreria: 100, lingH: 3000, lingP: 2000, lingO: 3000 },
  701: { id: 701, name: "Armadura Infame", type: "armor", objType: 3, value: 25060, graphic: 4911, skHerreria: 80, lingH: 250, lingP: 63, lingO: 0, defense: 38, defenseMin: 35, defenseMax: 40, bodyId: 162, forbiddenClasses: [2, 4, 5, 6] },
  703: { id: 703, name: "Tumba de Cronos", type: "misc", objType: 8, value: 0, graphic: 513, texto: "Aqui yace el alma de Cronos, un dios que ha dado mucho por nuestro mundo. Descansa, hermano... el pueblo de Argentum jamas te olvidara!" },
  704: { id: 704, name: "Arbol", type: "misc", objType: 4, value: 0, graphic: 30680 },
  705: { id: 705, name: "El Ojo del Demiurgo", type: "misc", objType: 24, value: 6000000, graphic: 609, spellId: 43 },
  706: { id: 706, name: "Cartel de Advertencia", type: "misc", objType: 8, value: 0, graphic: 500, texto: "PROHIBIDO TOCAR (dioses y semidioses incluidos!). Este pergamino fue encargado al imperio real por los dioses de Argentum para su estudio." },
  707: { id: 707, name: "Vestimenta de Noble (E/G)", type: "armor", objType: 3, value: 700, graphic: 13282, defense: 4, defenseMin: 3, defenseMax: 5, bodyId: 180 },
  708: { id: 708, name: "Escudo Infernal", type: "shield", objType: 16, value: 7800, graphic: 13255, skHerreria: 70, lingH: 60, lingP: 30, lingO: 0, anim: 5, defense: 3, defenseMin: 1, defenseMax: 4, forbiddenClasses: [2, 5, 6] },
  709: { id: 709, name: "Columna Egipcia", type: "misc", objType: 20, value: 0, graphic: 1460 },
  710: { id: 710, name: "Copa de Oro", type: "misc", objType: 21, value: 4000, graphic: 54 },
  711: { id: 711, name: "Tumba de Valkira", type: "misc", objType: 8, value: 0, graphic: 513, texto: "Aqui descansan los restos de la Diosa Valkira, quien dejo todo de ella para ser la gran fuerza ordenadora de estas tierras durante largas temporadas. El mundo de Argentum siempre te lo agradecera." },
  712: { id: 712, name: "Tumba de Jennifer", type: "misc", objType: 8, value: 0, graphic: 513, texto: "Aqui descansan los restos de Jennifer de Nix. Largo fue el camino desde su infancia como gitana hasta diosa de la ciudad del sur, quien lucho con los peores males que estas tierras han conocido. Que este mundo no olvide tu sacrificio y tu lucha contra los dioses malignos que gobernaron en otras epocas. Que tu hijo EL OSO vele por tu espiritu en este pacifico lugar." },
  713: { id: 713, name: "Tumba de Jareth", type: "misc", objType: 8, value: 0, graphic: 513, texto: "Aqui descansan los restos de Jareth. Antiguo luchador y lider del ejercito real de Banderbill. Que tu espiritu proteja a la ciudad." },
  714: { id: 714, name: "Tumba de Gold Fire", type: "misc", objType: 8, value: 0, graphic: 513, texto: "Aqui descansan los restos de Gold Fire. Lider supremo del ejercito de Banderbill en la septima era de este mundo." },
  715: { id: 715, name: "Tumba de Amenakhte", type: "misc", objType: 8, value: 0, graphic: 513, texto: "Aqui descansan los restos de Amenakhte. Lider supremo del ejercito de la legion oscura en la novena era, gano el respeto de este mundo a fuerza de espada y sangre." },
