  868: { id: 868, name: "Tumba de Chatillon", type: "misc", objType: 8, value: 0, graphic: 513, texto: "Yacen bajo esta tumba los restos del Gran Dios Chatillon, que dejo su vida por la gloria y el orden de estas tierras." },
  869: { id: 869, name: "Tumba de Nightsorrow", type: "misc", objType: 8, value: 0, graphic: 513, texto: "Aqui descansan los restos del Dios Nightsorrow, que mucho colaboro por la justicia del Argentum." },
  870: { id: 870, name: "Tumba de Shep", type: "misc", objType: 8, value: 0, graphic: 513, texto: "Bajo esta piedra reposan en paz los restos del gran Shep, aquel Dios que dedico su vida entera a estas tierras y sus habitantes." },
  871: { id: 871, name: "Tumba de Patrick", type: "misc", objType: 8, value: 0, graphic: 513, texto: "Yacen aqui los restos de Patrick, aquel bondadoso Dios que con esfuerzo y trabajo mucho dio por estas tierras." },
  872: { id: 872, name: "Tumba de EL OSO", type: "misc", objType: 8, value: 0, graphic: 513, texto: "Aqui descansan los restos del mitico EL OSO, poderoso Dios que durante siglos fue el responsable de darle el halito de vida a este hermoso mundo gracias a su gran ciencia, bondad y dedicacion. Por siempre el pueblo del Argentum glorificara tu paso por estas tierras y te estrara eternamente agradecido." },
